actions.script:
            success = false

            try {
                ec.logger.info("Minio AI 文件分析请求: ${bucketId}/${objectKey}, 类型: ${analysisType}")

                // 通过统一MCP服务获取Minio AI配置
                def configResult = ec.service.sync().name("mcp.ai.config.get#ModuleAiConfig")
                    .parameter("module", "minio")
                    .parameter("configType", "multimodal")
                    .call()

                if (!configResult.success || !configResult.config?.apiKey) {
                    ec.logger.warn("Minio AI配置获取失败，使用演示模式")
                    def demoResult = generateDemoFileAnalysis(objectKey, analysisType)
                    analysisResult = demoResult.analysisResult
                    contentSummary = demoResult.contentSummary
                    extractedText = demoResult.extractedText
                    detectedLanguage = demoResult.detectedLanguage
                    confidence = demoResult.confidence
                    success = true
                    return
                }

                def aiConfig = configResult.config

                // 获取文件信息和下载URL
                def fileInfo = getFileInfoAndUrl(bucketId, objectKey)

                // 根据文件类型选择分析策略
                def prompt = buildFileAnalysisPrompt(fileInfo, analysisType, extractText, generateSummary, detectLanguage)

                // 调用统一的MCP多模态分析服务
                def mcpResult
                if (fileInfo.mimeType?.startsWith("image/")) {
                    mcpResult = ec.service.sync().name("mcp.ai.analyze#Image")
                        .parameter("imageUrl", fileInfo.downloadUrl)
                        .parameter("prompt", prompt)
                        .parameter("module", "minio")
                        .parameter("aiProvider", aiConfig.provider)
                        .call()
                } else if (fileInfo.mimeType?.startsWith("audio/")) {
                    mcpResult = ec.service.sync().name("mcp.ai.analyze#Audio")
                        .parameter("audioUrl", fileInfo.downloadUrl)
                        .parameter("prompt", prompt)
                        .parameter("module", "minio")
                        .parameter("aiProvider", aiConfig.provider)
                        .call()
                } else {
                    mcpResult = ec.service.sync().name("mcp.ai.analyze#Document")
                        .parameter("documentUrl", fileInfo.downloadUrl)
                        .parameter("prompt", prompt)
                        .parameter("module", "minio")
                        .parameter("aiProvider", aiConfig.provider)
                        .call()
                }

                if (mcpResult.success) {
                    def result = parseFileAnalysisResponse(mcpResult.analysis, mcpResult.extractedData)
                    analysisResult = result.analysisResult
                    contentSummary = result.contentSummary
                    extractedText = result.extractedText
                    detectedLanguage = result.detectedLanguage
                    confidence = result.confidence
                    success = true
                    ec.logger.info("Minio 文件分析成功: ${objectKey}")
                } else {
                    ec.logger.warn("AI文件分析失败，使用演示模式: ${mcpResult.error}")
                    def demoResult = generateDemoFileAnalysis(objectKey, analysisType)
                    analysisResult = demoResult.analysisResult
                    contentSummary = demoResult.contentSummary
                    extractedText = demoResult.extractedText
                    detectedLanguage = demoResult.detectedLanguage
                    confidence = demoResult.confidence
                    success = true
                }

            } catch (Exception e) {
                ec.logger.error("Minio文件分析错误", e)
                success = false
                error = e.message
            }

            // 获取文件信息和下载URL
            def getFileInfoAndUrl(bucketId, objectKey) {
                try {
                    // 这里应该调用实际的Minio服务获取文件信息
                    // 暂时使用模拟数据
                    def fileExtension = objectKey.contains(".") ? objectKey.substring(objectKey.lastIndexOf(".") + 1) : ""
                    def mimeType = getMimeType(fileExtension)

                    return [
                        objectKey: objectKey,
                        fileName: objectKey.contains("/") ? objectKey.substring(objectKey.lastIndexOf("/") + 1) : objectKey,
                        fileExtension: fileExtension,
                        mimeType: mimeType,
                        downloadUrl: "minio://demo/${bucketId}/${objectKey}", // 模拟URL
                        fileSize: 1024 * (int)(Math.random() * 1000) // 模拟文件大小
                    ]
                } catch (Exception e) {
                    ec.logger.warn("获取文件信息失败", e)
                    return [objectKey: objectKey, mimeType: "application/octet-stream"]
                }
            }

            // 根据文件扩展名获取MIME类型
            def getMimeType(extension) {
                def mimeTypes = [
                    "pdf": "application/pdf",
                    "doc": "application/msword",
                    "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                    "xls": "application/vnd.ms-excel",
                    "xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    "ppt": "application/vnd.ms-powerpoint",
                    "pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
                    "txt": "text/plain",
                    "jpg": "image/jpeg",
                    "jpeg": "image/jpeg",
                    "png": "image/png",
                    "gif": "image/gif",
                    "bmp": "image/bmp",
                    "mp3": "audio/mpeg",
                    "wav": "audio/wav",
                    "mp4": "video/mp4",
                    "avi": "video/x-msvideo"
                ]
                return mimeTypes[extension.toLowerCase()] ?: "application/octet-stream"
            }

            // 构建文件分析提示词
            def buildFileAnalysisPrompt(fileInfo, analysisType, extractText, generateSummary, detectLanguage) {
                def prompt = """作为Minio智能文件管理专家，请分析以下文件：

文件信息：
- 文件名: ${fileInfo.fileName}
- 文件类型: ${fileInfo.mimeType}
- 文件大小: ${fileInfo.fileSize} 字节

分析要求：
${analysisType == 'document' ? '文档分析：提取关键内容、主题、结构分析' :
  analysisType == 'image' ? '图像分析：识别对象、文字、场景、色彩分析' :
  analysisType == 'audio' ? '音频分析：语音识别、音乐识别、音质分析' :
  '通用分析：根据文件类型进行智能识别和分析'}

${extractText ? '- 提取文件中的文本内容' : ''}
${generateSummary ? '- 生成内容摘要和关键要点' : ''}
${detectLanguage ? '- 检测文件语言' : ''}

请提供详细的分析结果：
1. 文件内容概述
2. 关键信息提取
3. 智能标签和分类建议
4. 搜索关键词推荐

请用JSON格式返回结果：
{
  "contentSummary": "内容摘要",
  "extractedText": "提取的文本内容",
  "detectedLanguage": "检测到的语言",
  "keyTags": ["标签1", "标签2", "标签3"],
  "categories": ["分类1", "分类2"],
  "searchKeywords": ["关键词1", "关键词2", "关键词3"],
  "analysisDetails": {
    "contentType": "内容类型",
    "mainTopics": ["主题1", "主题2"],
    "qualityScore": "质量评分(0-1)",
    "metadata": {"key": "value"}
  },
  "confidence": "分析置信度(0-1)"
}"""
                return prompt
            }

            // 解析文件分析响应
            def parseFileAnalysisResponse(analysis, extractedData) {
                try {
                    def jsonPattern = /\{[\s\S]*\}/
                    def jsonMatcher = analysis =~ jsonPattern

                    if (jsonMatcher) {
                        def jsonText = jsonMatcher[0]
                        def result = new groovy.json.JsonSlurper().parseText(jsonText)

                        return [
                            analysisResult: [
                                keyTags: result.keyTags ?: [],
                                categories: result.categories ?: [],
                                searchKeywords: result.searchKeywords ?: [],
                                analysisDetails: result.analysisDetails ?: [:]
                            ],
                            contentSummary: result.contentSummary ?: "文件分析完成",
                            extractedText: result.extractedText ?: extractedData?.text ?: "",
                            detectedLanguage: result.detectedLanguage ?: "zh",
                            confidence: result.confidence ?: 0.8
                        ]
                    }
                } catch (Exception e) {
                    ec.logger.error("文件分析响应解析错误", e)
                }

                return generateDemoFileAnalysis(objectKey, analysisType)
            }

            // 演示模式文件分析
            def generateDemoFileAnalysis(objectKey, analysisType) {
                def fileName = objectKey.contains("/") ? objectKey.substring(objectKey.lastIndexOf("/") + 1) : objectKey
                def fileExtension = fileName.contains(".") ? fileName.substring(fileName.lastIndexOf(".") + 1) : ""

                def demoResults = [:]

                switch (analysisType) {
                    case "document":
                        demoResults = [
                            contentSummary: "这是一个包含业务报告和数据分析的文档，主要讨论了市场趋势和销售策略。",
                            extractedText: "业务报告\\n\\n1. 市场概况\\n   - 增长率: 15%\\n   - 竞争对手分析\\n\\n2. 销售策略\\n   - 目标客户群体\\n   - 产品定位",
                            detectedLanguage: "zh",
                            analysisResult: [
                                keyTags: ["商业文档", "数据分析", "市场报告"],
                                categories: ["业务文档", "分析报告"],
                                searchKeywords: ["市场", "销售", "策略", "数据", "分析"],
                                analysisDetails: [
                                    contentType: "商业报告",
                                    mainTopics: ["市场分析", "销售策略", "数据统计"],
                                    qualityScore: 0.9,
                                    metadata: [documentPages: 5, hasCharts: true]
                                ]
                            ]
                        ]
                        break
                    case "image":
                        demoResults = [
                            contentSummary: "图像包含产品展示场景，识别到商品、文字标识和背景环境。",
                            extractedText: "产品名称：智能设备\\n型号：AI-2024\\n特色功能",
                            detectedLanguage: "zh",
                            analysisResult: [
                                keyTags: ["产品图片", "商品展示", "智能设备"],
                                categories: ["产品图像", "营销素材"],
                                searchKeywords: ["产品", "设备", "展示", "商品"],
                                analysisDetails: [
                                    contentType: "产品图片",
                                    mainTopics: ["产品展示", "商品特征"],
                                    qualityScore: 0.85,
                                    metadata: [resolution: "1920x1080", hasText: true, objectCount: 3]
                                ]
                            ]
                        ]
                        break
                    case "audio":
                        demoResults = [
                            contentSummary: "音频文件包含会议记录内容，讨论了项目进展和下一步计划。",
                            extractedText: "会议记录\\n时间：2024年11月\\n参会人员：项目团队\\n主要议题：项目进展汇报\\n行动项：完成第一阶段开发",
                            detectedLanguage: "zh",
                            analysisResult: [
                                keyTags: ["会议录音", "项目讨论", "工作记录"],
                                categories: ["会议音频", "工作记录"],
                                searchKeywords: ["会议", "项目", "讨论", "计划"],
                                analysisDetails: [
                                    contentType: "会议录音",
                                    mainTopics: ["项目进展", "工作计划"],
                                    qualityScore: 0.8,
                                    metadata: [duration: "45分钟", speakerCount: 4, hasTranscript: true]
                                ]
                            ]
                        ]
                        break
                    default: // general
                        demoResults = [
                            contentSummary: "文件分析完成，识别为${fileExtension.toUpperCase()}格式文件，包含可搜索的内容。",
                            extractedText: "文件内容摘要\\n${fileName}\\n文件类型：${fileExtension}",
                            detectedLanguage: "zh",
                            analysisResult: [
                                keyTags: ["${fileExtension}文件", "数据文件", fileName.take(10)],
                                categories: ["通用文件", "${fileExtension}格式"],
                                searchKeywords: [fileName.take(10), fileExtension, "文件"],
                                analysisDetails: [
                                    contentType: "${fileExtension}文件",
                                    mainTopics: ["文件管理"],
                                    qualityScore: 0.7,
                                    metadata: [fileFormat: fileExtension, analyzed: true]
                                ]
                            ]
                        ]
                }

                demoResults.confidence = 0.75
                return demoResults
            }

            success = false

            try {
                ec.logger.info("Minio AI 批量文件分类请求: ${bucketId}, 文件数量: ${fileList.size()}")

                // 通过统一MCP服务获取Minio AI配置
                def configResult = ec.service.sync().name("mcp.ai.config.get#ModuleAiConfig")
                    .parameter("module", "minio")
                    .parameter("configType", "text")
                    .call()

                if (!configResult.success || !configResult.config?.apiKey) {
                    ec.logger.warn("Minio AI配置获取失败，使用演示模式")
                    def demoResult = generateDemoFileClassification(fileList, autoTag)
                    classificationResults = demoResult.classificationResults
                    suggestedCategories = demoResult.suggestedCategories
                    processingStats = demoResult.processingStats
                    success = true
                    return
                }

                def aiConfig = configResult.config

                // 构建批量分类提示词
                def prompt = buildBatchClassificationPrompt(fileList, classificationRules, autoTag)

                // 调用统一的MCP批量分析服务
                def mcpResult = ec.service.sync().name("mcp.ai.process#BatchClassification")
                    .parameter("items", fileList)
                    .parameter("classificationPrompt", prompt)
                    .parameter("module", "minio")
                    .parameter("aiProvider", aiConfig.provider)
                    .parameter("batchSize", 10)
                    .call()

                if (mcpResult.success) {
                    def result = parseBatchClassificationResponse(mcpResult.classifications, mcpResult.suggestions)
                    classificationResults = result.classificationResults
                    suggestedCategories = result.suggestedCategories
                    processingStats = result.processingStats
                    success = true
                    ec.logger.info("Minio 批量分类成功: 处理${classificationResults.size()}个文件")
                } else {
                    ec.logger.warn("AI批量分类失败，使用演示模式: ${mcpResult.error}")
                    def demoResult = generateDemoFileClassification(fileList, autoTag)
                    classificationResults = demoResult.classificationResults
                    suggestedCategories = demoResult.suggestedCategories
                    processingStats = demoResult.processingStats
                    success = true
                }

            } catch (Exception e) {
                ec.logger.error("Minio批量分类错误", e)
                success = false
                error = e.message
            }

            // 构建批量分类提示词
            def buildBatchClassificationPrompt(fileList, classificationRules, autoTag) {
                def prompt = """作为Minio智能文件管理专家，请对以下文件进行批量智能分类：

文件列表：
${fileList.collect { "- ${it.fileName ?: it.objectKey} (${it.fileSize ?: 'Unknown'} bytes)" }.join('\n')}

分类要求：
1. 根据文件类型、名称、大小等特征进行智能分类
2. 生成统一的目录结构建议
3. 为每个文件推荐合适的标签
${autoTag ? '4. 自动生成智能标签' : ''}

${classificationRules ? '自定义分类规则：' + classificationRules.join('\\n') : ''}

请用JSON格式返回结果：
{
  "classifications": [
    {
      "fileName": "文件名",
      "suggestedCategory": "建议分类",
      "tags": ["标签1", "标签2"],
      "confidence": "分类置信度",
      "reason": "分类理由"
    }
  ],
  "categoryStructure": {
    "documents": {"business": [], "personal": []},
    "images": {"products": [], "presentations": []},
    "media": {"audio": [], "video": []}
  },
  "processingStats": {
    "totalFiles": "文件总数",
    "categoriesGenerated": "生成分类数",
    "averageConfidence": "平均置信度"
  }
}"""
                return prompt
            }

            // 解析批量分类响应
            def parseBatchClassificationResponse(classifications, suggestions) {
                try {
                    def jsonPattern = /\{[\s\S]*\}/
                    def jsonMatcher = classifications =~ jsonPattern

                    if (jsonMatcher) {
                        def jsonText = jsonMatcher[0]
                        def result = new groovy.json.JsonSlurper().parseText(jsonText)

                        def categories = []
                        result.categoryStructure?.each { category, subcategories ->
                            categories.add(category)
                            if (subcategories instanceof Map) {
                                categories.addAll(subcategories.keySet())
                            }
                        }

                        return [
                            classificationResults: result.classifications ?: [],
                            suggestedCategories: categories.unique(),
                            processingStats: result.processingStats ?: [:]
                        ]
                    }
                } catch (Exception e) {
                    ec.logger.error("批量分类响应解析错误", e)
                }

                return generateDemoFileClassification(fileList, autoTag)
            }

            // 演示模式文件分类
            def generateDemoFileClassification(fileList, autoTag) {
                def classificationResults = []
                def categoryCounts = [documents: 0, images: 0, media: 0, data: 0, other: 0]

                fileList.each { file ->
                    def fileName = file.fileName ?: file.objectKey ?: "unknown"
                    def extension = fileName.contains(".") ? fileName.substring(fileName.lastIndexOf(".") + 1).toLowerCase() : ""

                    def category = "other"
                    def tags = []
                    def confidence = 0.8

                    // 根据文件扩展名分类
                    if (extension in ["pdf", "doc", "docx", "txt", "rtf"]) {
                        category = "documents"
                        tags = ["文档", "办公", extension.toUpperCase()]
                        confidence = 0.95
                    } else if (extension in ["jpg", "jpeg", "png", "gif", "bmp", "svg"]) {
                        category = "images"
                        tags = ["图片", "图像", extension.toUpperCase()]
                        confidence = 0.9
                    } else if (extension in ["mp3", "wav", "mp4", "avi", "mov"]) {
                        category = "media"
                        tags = ["媒体", "音视频", extension.toUpperCase()]
                        confidence = 0.9
                    } else if (extension in ["xlsx", "xls", "csv", "json", "xml"]) {
                        category = "data"
                        tags = ["数据", "表格", extension.toUpperCase()]
                        confidence = 0.85
                    }

                    if (autoTag) {
                        // 基于文件名添加智能标签
                        if (fileName.toLowerCase().contains("report")) tags.add("报告")
                        if (fileName.toLowerCase().contains("project")) tags.add("项目")
                        if (fileName.toLowerCase().contains("meeting")) tags.add("会议")
                        if (fileName.toLowerCase().contains("backup")) tags.add("备份")
                    }

                    categoryCounts[category]++

                    classificationResults.add([
                        fileName: fileName,
                        suggestedCategory: category,
                        tags: tags,
                        confidence: confidence,
                        reason: "基于文件扩展名${extension}和文件名模式分析"
                    ])
                }

                return [
                    classificationResults: classificationResults,
                    suggestedCategories: ["documents", "images", "media", "data", "projects", "backups"],
                    processingStats: [
                        totalFiles: fileList.size(),
                        categoriesGenerated: categoryCounts.size(),
                        averageConfidence: 0.88,
                        categoryDistribution: categoryCounts
                    ]
                ]
            }

            success = false

            try {
                ec.logger.info("Minio AI 存储优化分析请求: ${bucketId}, 范围: ${analysisScope}")

                // 通过统一MCP服务获取Minio AI配置
                def configResult = ec.service.sync().name("mcp.ai.config.get#ModuleAiConfig")
                    .parameter("module", "minio")
                    .parameter("configType", "text")
                    .call()

                if (!configResult.success || !configResult.config?.apiKey) {
                    ec.logger.warn("Minio AI配置获取失败，使用演示模式")
                    def demoResult = generateDemoStorageOptimization(bucketId, optimizationType)
                    optimizationReport = demoResult.optimizationReport
                    recommendations = demoResult.recommendations
                    potentialSavings = demoResult.potentialSavings
                    actionPlan = demoResult.actionPlan
                    success = true
                    return
                }

                def aiConfig = configResult.config

                // 获取存储使用情况数据
                def storageData = getStorageAnalysisData(bucketId, analysisScope)

                // 构建存储优化提示词
                def prompt = buildStorageOptimizationPrompt(storageData, optimizationType)

                // 调用统一的MCP优化分析服务
                def mcpResult = ec.service.sync().name("mcp.ai.optimize#Storage")
                    .parameter("storageData", storageData)
                    .parameter("optimizationType", optimizationType)
                    .parameter("module", "minio")
                    .parameter("aiProvider", aiConfig.provider)
                    .parameter("prompt", prompt)
                    .call()

                if (mcpResult.success) {
                    def result = parseStorageOptimizationResponse(mcpResult.optimizationPlan, mcpResult.savings)
                    optimizationReport = result.optimizationReport
                    recommendations = result.recommendations
                    potentialSavings = result.potentialSavings
                    actionPlan = result.actionPlan
                    success = true
                    ec.logger.info("Minio 存储优化分析成功")
                } else {
                    ec.logger.warn("AI存储优化失败，使用演示模式: ${mcpResult.error}")
                    def demoResult = generateDemoStorageOptimization(bucketId, optimizationType)
                    optimizationReport = demoResult.optimizationReport
                    recommendations = demoResult.recommendations
                    potentialSavings = demoResult.potentialSavings
                    actionPlan = demoResult.actionPlan
                    success = true
                }

            } catch (Exception e) {
                ec.logger.error("Minio存储优化错误", e)
                success = false
                error = e.message
            }

            // 获取存储分析数据
            def getStorageAnalysisData(bucketId, analysisScope) {
                try {
                    // 模拟存储数据获取
                    def storageData = [
                        totalStorage: 5368709120L, // 5GB
                        usedStorage: 3221225472L,  // 3GB
                        fileCount: 1250,
                        averageFileSize: 2577408L,  // ~2.5MB
                        buckets: 5,
                        largestFiles: [
                            [name: "backup_20241101.zip", size: 1073741824L], // 1GB
                            [name: "video_presentation.mp4", size: 536870912L], // 512MB
                            [name: "dataset_export.csv", size: 268435456L] // 256MB
                        ],
                        fileTypeDistribution: [
                            "documents": 35,
                            "images": 40,
                            "media": 15,
                            "data": 8,
                            "other": 2
                        ],
                        duplicateFiles: [
                            [name: "report_copy.pdf", size: 10485760L, count: 3],
                            [name: "image_backup.jpg", size: 5242880L, count: 2]
                        ],
                        oldFiles: [
                            [name: "old_backup_2023.zip", size: 209715200L, lastAccessed: "2024-01-15"],
                            [name: "temp_files.tar", size: 52428800L, lastAccessed: "2024-02-20"]
                        ]
                    ]

                    return storageData
                } catch (Exception e) {
                    ec.logger.warn("获取存储数据失败，使用默认数据", e)
                    return [totalStorage: 1073741824L, usedStorage: 536870912L, fileCount: 100]
                }
            }

            // 构建存储优化提示词
            def buildStorageOptimizationPrompt(storageData, optimizationType) {
                def prompt = """作为Minio存储优化专家，请分析以下存储使用情况并提供优化建议：

存储概况：
- 总容量: ${(storageData.totalStorage / 1024 / 1024 / 1024).round(2)} GB
- 已使用: ${(storageData.usedStorage / 1024 / 1024 / 1024).round(2)} GB
- 使用率: ${((storageData.usedStorage * 100) / storageData.totalStorage).round(1)}%
- 文件总数: ${storageData.fileCount}
- 平均文件大小: ${(storageData.averageFileSize / 1024 / 1024).round(2)} MB

文件类型分布：
${storageData.fileTypeDistribution?.collect { type, percent -> "- ${type}: ${percent}%" }.join('\n')}

大文件清单：
${storageData.largestFiles?.collect { "- ${it.name}: ${(it.size / 1024 / 1024).round()} MB" }.join('\n')}

重复文件：
${storageData.duplicateFiles?.collect { "- ${it.name}: ${it.count}个副本" }.join('\n')}

长期未访问文件：
${storageData.oldFiles?.collect { "- ${it.name}: 最后访问 ${it.lastAccessed}" }.join('\n')}

优化目标：${optimizationType == 'space' ? '空间优化' : optimizationType == 'cost' ? '成本优化' : '性能优化'}

请提供优化分析和建议：
1. 存储使用情况分析
2. 优化机会识别
3. 潜在节省评估
4. 具体行动计划

请用JSON格式返回结果：
{
  "optimizationReport": {
    "currentUsage": "当前使用分析",
    "inefficiencies": ["效率问题1", "效率问题2"],
    "opportunities": ["优化机会1", "优化机会2"]
  },
  "recommendations": [
    {
      "category": "优化类别",
      "action": "具体行动",
      "impact": "预期影响",
      "priority": "优先级",
      "estimatedSavings": "预估节省"
    }
  ],
  "potentialSavings": {
    "storageSpace": "可节省空间(GB)",
    "costReduction": "成本降低(%)",
    "performanceGain": "性能提升(%)"
  },
  "actionPlan": [
    "行动项目1",
    "行动项目2",
    "行动项目3"
  ]
}"""
                return prompt
            }

            // 解析存储优化响应
            def parseStorageOptimizationResponse(optimizationPlan, savings) {
                try {
                    def jsonPattern = /\{[\s\S]*\}/
                    def jsonMatcher = optimizationPlan =~ jsonPattern

                    if (jsonMatcher) {
                        def jsonText = jsonMatcher[0]
                        def result = new groovy.json.JsonSlurper().parseText(jsonText)

                        return [
                            optimizationReport: result.optimizationReport ?: [:],
                            recommendations: result.recommendations ?: [],
                            potentialSavings: result.potentialSavings ?: [:],
                            actionPlan: result.actionPlan ?: []
                        ]
                    }
                } catch (Exception e) {
                    ec.logger.error("存储优化响应解析错误", e)
                }

                return generateDemoStorageOptimization(bucketId, optimizationType)
            }

